    'Address in links' => 'Endereço nos links',
    'Emails link to ITFlow with %s in config.php - set it to the address you reach ITFlow on.' => 'Os e-mails apontam para o ITFlow com %s no config.php - defina-o como o endereço em que você acessa o ITFlow.',
